const terminalTarget = `-- name: TerminalTarget :one
SELECT r.id AS resource_id,
       (SELECT i.id FROM gateway_instance i
        WHERE r.gateway_id IS NOT NULL AND i.gateway_id = r.gateway_id AND i.org_id = r.org_id
          AND i.last_seen_at > now() - interval '45 seconds' AND r.type = ANY(i.connectors)
        ORDER BY random() LIMIT 1) AS instance_id
FROM resource r
WHERE r.org_id = $1 AND r.name = $2
`

type TerminalTargetParams struct {
	OrgID uuid.UUID
	Name  string
}

type TerminalTargetRow struct {
	ResourceID uuid.UUID
	InstanceID uuid.UUID
}

// The resource by name with a random online instance of its pool serving its
// type; instance_id is NULL (scanned as uuid.Nil) without a pool or an online instance.
func (q *Queries) TerminalTarget(ctx context.Context, arg TerminalTargetParams) (TerminalTargetRow, error) {
	row := q.db.QueryRow(ctx, terminalTarget, arg.OrgID, arg.Name)
	var i TerminalTargetRow
	err := row.Scan(&i.ResourceID, &i.InstanceID)
	return i, err
}

const updateSessionCounters = `-- name: UpdateSessionCounters :exec
UPDATE session s
SET bytes_up = GREATEST(s.bytes_up, c.bytes_up), bytes_down = GREATEST(s.bytes_down, c.bytes_down),
    datagrams_up = GREATEST(s.datagrams_up, c.datagrams_up), datagrams_down = GREATEST(s.datagrams_down, c.datagrams_down)
FROM (SELECT unnest($3::uuid[]) AS id, unnest($4::bigint[]) AS bytes_up, unnest($5::bigint[]) AS bytes_down,
             unnest($6::bigint[]) AS datagrams_up, unnest($7::bigint[]) AS datagrams_down) c
WHERE s.id = c.id AND s.org_id = $1 AND s.gateway_instance_id = $2::uuid AND s.ended_at IS NULL
`

type UpdateSessionCountersParams struct {
	OrgID         uuid.UUID
	InstanceID    uuid.UUID
	Ids           []uuid.UUID
	BytesUp       []int64
	BytesDown     []int64
	DatagramsUp   []int64
	DatagramsDown []int64
}

// One statement for a batch; only open sessions of the instance, never lowering a counter.
func (q *Queries) UpdateSessionCounters(ctx context.Context, arg UpdateSessionCountersParams) error {
	_, err := q.db.Exec(ctx, updateSessionCounters,
		arg.OrgID,
		arg.InstanceID,
		arg.Ids,
		arg.BytesUp,
		arg.BytesDown,
		arg.DatagramsUp,
		arg.DatagramsDown,
	)
	return err
}
